3	const STORAGE_KEY = "convertscan:monitored_urls";
4	
5	export function useMonitoring() {
6	  const [monitoredUrls, setMonitoredUrls] = useState<Set<string>>(() => {
7	    try {
8	      const stored = localStorage.getItem(STORAGE_KEY);
9	      return stored ? new Set(JSON.parse(stored) as string[]) : new Set();
10	    } catch {
11	      return new Set();
12	    }
13	  });
14	
15	  const toggleMonitoring = (url: string) => {
16	    setMonitoredUrls((prev) => {
17	      const next = new Set(prev);
18	      if (next.has(url)) {
19	        next.delete(url);
20	      } else {
21	        next.add(url);
22	      }
23	      try {
24	        localStorage.setItem(STORAGE_KEY, JSON.stringify([...next]));
25	      } catch {
26	        /* ignore storage errors */
27	      }
28	      return next;
29	    });
30	  };
31	
32	  const isMonitored = (url: string) => monitoredUrls.has(url);
33	
34	  return { monitoredUrls, toggleMonitoring, isMonitored };
35	}
